<?php
namespace App\Service;
use PDO;
trait FinanceMatchingRuleManualTrait
{
 public static function manualClassifyBankTransaction(PDO $pdo,int $bankTxId,array $data,array $user):array{
  $mode=strtolower(trim((string)($data['distribution_mode']??'manual')));
  if($mode!=='manual'||!empty($data['create_rule']))throw new \InvalidArgumentException('Режим «Только эту операцию» не создаёт правила разнесения.');
  $own=false;if(!$pdo->inTransaction()){$pdo->beginTransaction();$own=true;}
  try{
   $q=$pdo->prepare('SELECT * FROM bank_transactions WHERE id=? FOR UPDATE');$q->execute([$bankTxId]);$tx=$q->fetch(PDO::FETCH_ASSOC);if(!$tx)throw new \InvalidArgumentException('Банковская операция не найдена.');if(!empty($tx['is_internal_transfer']))throw new \InvalidArgumentException('Банковская операция уже оформлена как внутренний перевод.');
   $direction=self::directionForTransaction($tx);if($direction===null)throw new \InvalidArgumentException('Не удалось определить направление операции.');
   $action=trim((string)($data['action_type']??'categorize'));if(!in_array($action,['categorize','employee_cash_settlement'],true))throw new \InvalidArgumentException('Этот тип ручного разнесения недоступен.');
   $cfu=self::nullableInt($data['cash_flow_center_id']??$data['target_cash_flow_center_id']??null);$dds=self::nullableInt($data['dds_category_id']??$data['target_dds_category_id']??null);if($cfu===null||$dds===null)throw new \InvalidArgumentException('Выберите ЦФУ и статью ДДС.');self::assertCfu($pdo,$cfu);self::assertDds($pdo,$dds,$direction);FinanceStructureService::assertAllowedPair($pdo,$cfu,$dds,$direction);
   if($action==='employee_cash_settlement'){
    $employeeType=self::nullableString($data['target_employee_identity_type']??null);$employeeId=self::nullableInt($data['target_employee_identity_id']??null);$employeeName=self::nullableString($data['target_employee_name_snapshot']??null);if(!in_array($employeeType,[FinanceEmployeePaymentService::IDENTITY_TENANT_USER,FinanceEmployeePaymentService::IDENTITY_COMPANY_USER],true)||$employeeId===null||$employeeName===null)throw new \InvalidArgumentException('Для взаиморасчёта выберите сотрудника.');
    $employee=['identity_type'=>$employeeType,'identity_id'=>$employeeId,'full_name'=>$employeeName,'role_code'=>(string)($data['target_employee_role_snapshot']??'')];
    $result=FinanceEmployeeBankSettlementService::settleBankTransaction($pdo,$bankTxId,$employee,$user,null,$cfu,$dds);
    if($own)$pdo->commit();return $result+['rule_id'=>null,'status'=>'MANUAL','action_type'=>$action];
   }
   $q=$pdo->prepare("SELECT id FROM finance_operations WHERE bank_transaction_id=? AND status!='CANCELLED' ORDER BY id LIMIT 1 FOR UPDATE");$q->execute([$bankTxId]);$opId=(int)($q->fetchColumn()?:0);
   $q=$pdo->prepare("UPDATE bank_transactions SET cash_flow_center_id=?,dds_category_id=?,classification_status='MANUAL',classification_rule_id=NULL,classification_locked=1,classification_updated_at=NOW() WHERE id=?");$q->execute([$cfu,$dds,$bankTxId]);
   if($opId){$q=$pdo->prepare("UPDATE finance_operations SET cash_flow_center_id=?,dds_category_id=?,classification_status='MANUAL',classification_rule_id=NULL,classification_locked=1,classification_updated_at=NOW() WHERE id=?");$q->execute([$cfu,$dds,$opId]);}
   FinanceAuditLogService::log($pdo,'bank_transaction',$bankTxId,'classification_manual_single',null,['cash_flow_center_id'=>$cfu,'dds_category_id'=>$dds,'action_type'=>$action,'matching_rule_created'=>false],(int)($user['id']??0),(string)($user['role']??'company_owner'));
   if($own)$pdo->commit();return ['bank_transaction_id'=>$bankTxId,'operation_id'=>$opId?:null,'rule_id'=>null,'status'=>'MANUAL','action_type'=>$action];
  }catch(\Throwable $e){if($own&&$pdo->inTransaction())$pdo->rollBack();throw $e;}
 }
 public static function clearBankTransactionClassification(PDO $pdo,int $bankTxId,array $user):array{$own=false;if(!$pdo->inTransaction()){$pdo->beginTransaction();$own=true;}try{$q=$pdo->prepare('SELECT * FROM bank_transactions WHERE id=? FOR UPDATE');$q->execute([$bankTxId]);$tx=$q->fetch(PDO::FETCH_ASSOC);if(!$tx)throw new \InvalidArgumentException('Банковская операция не найдена.');if(!empty($tx['is_internal_transfer']))throw new \InvalidArgumentException('Разнесение внутреннего перевода нельзя удалить этим действием.');$status=strtoupper((string)($tx['classification_status']??'UNALLOCATED'));if(!in_array($status,['AUTO','MANUAL'],true))throw new \InvalidArgumentException('У операции нет сохранённого ручного или автоматического разнесения.');$q=$pdo->prepare("UPDATE bank_transactions SET cash_flow_center_id=NULL,dds_category_id=NULL,classification_status='UNALLOCATED',classification_rule_id=NULL,classification_locked=0,classification_updated_at=NOW() WHERE id=?");$q->execute([$bankTxId]);$q=$pdo->prepare("SELECT id FROM finance_operations WHERE bank_transaction_id=? AND status!='CANCELLED' FOR UPDATE");$q->execute([$bankTxId]);$operationIds=array_map('intval',$q->fetchAll(PDO::FETCH_COLUMN));if($operationIds){$placeholders=implode(',',array_fill(0,count($operationIds),'?'));$u=$pdo->prepare("UPDATE finance_operations SET cash_flow_center_id=NULL,dds_category_id=NULL,classification_status='UNALLOCATED',classification_rule_id=NULL,classification_locked=0,classification_updated_at=NOW() WHERE id IN ($placeholders)");$u->execute($operationIds);}$reapply=null;if($status==='MANUAL'&&$operationIds)$reapply=self::applyAutoMatchToOperation($pdo,$operationIds[0]);$check=$pdo->prepare('SELECT classification_status,classification_rule_id FROM bank_transactions WHERE id=?');$check->execute([$bankTxId]);$after=$check->fetch(PDO::FETCH_ASSOC)?:['classification_status'=>'UNALLOCATED','classification_rule_id'=>null];if($own)$pdo->commit();return ['bank_transaction_id'=>$bankTxId,'operation_ids'=>$operationIds,'previous_status'=>$status,'status'=>(string)$after['classification_status'],'rule_id'=>self::nullableInt($after['classification_rule_id']??null),'reapply'=>$reapply];}catch(\Throwable $e){if($own&&$pdo->inTransaction())$pdo->rollBack();throw $e;}}
}
